package com.gamehub;
import com.gamehub.infrastructure.Database; import com.gamehub.application.UserService; import javafx.application.Application; import javafx.geometry.Insets; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.Stage;
public final class GameHubApp extends Application {
 private Database db; private UserService users;
 public void start(Stage stage){try{db=new Database();users=new UserService(db);}catch(Exception e){new Alert(Alert.AlertType.ERROR,"Database startup failed: "+e.getMessage()).showAndWait();return;} login(stage);}
 private void login(Stage s){TextField u=new TextField();u.setPromptText("Username");PasswordField p=new PasswordField();p.setPromptText("Password");Label m=new Label();Button b=new Button("Sign in"),setup=new Button("Create first manager");b.setOnAction(e->{try{var x=users.authenticate(u.getText(),p.getText());if(x==null)m.setText("Invalid credentials");else dashboard(s,x.username(),x.role().name());}catch(Exception ex){m.setText(ex.getMessage());}});setup.setOnAction(e->{TextInputDialog a=new TextInputDialog();a.setHeaderText("Manager username");var un=a.showAndWait();if(un.isEmpty())return;TextInputDialog q=new TextInputDialog();q.setHeaderText("Password (8+ chars)");var pw=q.showAndWait();if(pw.isEmpty())return;try{users.bootstrap(un.get(),pw.get());m.setText("Manager created; sign in.");}catch(Exception ex){m.setText(ex.getMessage());}});VBox v=new VBox(12,new Label("GAMEHUB"),u,p,b,setup,m);v.setPadding(new Insets(40));s.setScene(new Scene(v,700,450));s.setTitle("GameHub");s.show();}
 private void dashboard(Stage s,String n,String r){VBox v=new VBox(16);v.setPadding(new Insets(30));v.getChildren().addAll(new Label("Welcome, "+n+" · "+r),new Label("GameHub dashboard"),new Button("Reservations"),new Button("Gaming stations"),new Button("Tournaments"),new Button("Maintenance"),new Button("Reports"));s.setScene(new Scene(v,700,450));}
 public void stop(){try{if(db!=null)db.close();}catch(Exception ignored){}} public static void main(String[]a){launch(a);}
}
